const CHART_SECONDS = [3, 7, 15]; // длительность прослушивания по попыткам
const previewCache = new Map();   // 'artist title' -> {previewUrl, artwork} | null

/** Ищет превью в iTunes: RU-стор, затем US. Возвращает null, если трека нет. */
async function resolvePreview(track, fetchImpl = fetch) {
  const key = `${track.artist} ${track.title}`.toLowerCase();
  if (previewCache.has(key)) return previewCache.get(key);
  const term = encodeURIComponent(`${track.artist} ${track.title}`);
  for (const country of ['RU', 'US']) {
    try {
      const ctl = new AbortController();
      const timer = setTimeout(() => ctl.abort(), 4500);
      const res = await fetchImpl(
        `https://itunes.apple.com/search?term=${term}&media=music&entity=song&limit=8&country=${country}`,
        { signal: ctl.signal },
      );
      clearTimeout(timer);
      if (!res.ok) continue;
      const data = await res.json();
      const withPreview = (data.results || []).filter((r) => r.previewUrl);
      // предпочитаем оригинального исполнителя (иначе первым лезет караоке-кавер)
      const na = normalize(track.artist);
      const hit = withPreview.find((r) => {
        const ra = normalize(r.artistName || '');
        return ra.includes(na) || na.includes(ra);
      }) || withPreview[0];
      if (hit) {
        const out = {
          previewUrl: hit.previewUrl,
          artwork: (hit.artworkUrl100 || '').replace('100x100', '300x300') || null,
        };
        previewCache.set(key, out);
        return out;
      }
    } catch { /* таймаут/сеть — пробуем следующий стор */ }
  }
  previewCache.set(key, null);
  return null;
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^а-яa-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Совпадение: точное с алиасом/заголовком, вхождение, либо ≥60% общих слов. */
export function matchesGuess(guess, melody) {
  const g = normalize(guess);
  if (!g || g.length < 3) return false;
  const targets = [melody.title, melody.artist, ...(melody.aliases || [])].filter(Boolean).map(normalize);
  for (const t of targets) {
    if (!t) continue;
    if (g === t || t.includes(g) && g.length >= Math.min(5, t.length) || g.includes(t)) return true;
    const gw = new Set(g.split(' ').filter((w) => w.length > 2));
    const tw = t.split(' ').filter((w) => w.length > 2);
    if (tw.length && gw.size) {
      const hit = tw.filter((w) => gw.has(w)).length;
      if (hit / tw.length >= 0.6) return true;
    }
  }
  return false;
}

const ATTEMPT_NOTES = [4, 8, Infinity];
const ATTEMPT_POINTS = [30, 20, 10];

export class MelodyEngine extends BaseGame {
  constructor(room = null, io = null, options = {}) {
    super(room, io);
    this.settings = room?.settings ?? {};
    const cfg = this.settings.melodyConfig || {};
    this.maxRounds = Math.max(3, Math.min(15, Number(cfg.rounds) || 7));
    this.attemptTime = Math.max(8, Math.min(40, Number(cfg.attemptTime) || 15));
    this.hintsEnabled = cfg.hints !== false;
    this.mode = cfg.mode === 'chart' ? 'chart' : 'notes';
    this._resolvePreview = options.resolvePreview || resolvePreview; // инъекция для тестов
    this.chartPool = null;        // null = резолвится; [] = не удалось
    this._chartRetries = 0;

    this.players = (room?.players || []).filter((p) => !p.isSpectator).map((p) => ({ id: p.id, name: p.name, score: 0 }));
    this.phase = 'waiting';
    this.round = 0;
    this.attempt = 0;
    this.current = null;
    // Хост может ограничить категории (нот-режим); пустой выбор = все
    const cats = Array.isArray(cfg.categories) ? cfg.categories.filter(Boolean) : [];
    const filtered = cats.length ? MELODIES.filter((m) => cats.includes(m.category)) : MELODIES;
    this._notesBank = filtered.length ? filtered : MELODIES;
    this.pool = shuffle(this._notesBank);
    this.poolIdx = 0;
    this._cooldown = new Map();     // playerId -> ts последней попытки
    this._hintUsedThisAttempt = false;
    this._roundWinner = null;
    this.stateVersion = 0;
  }

  touch() { this.stateVersion++; }
  getPlayer(id) { return this.players.find((p) => p.id === id) || null; }

  host(text) { this.emit('melody:host', { name: HOST_NAME, text }); }

  start() {
    this.phase = 'intro';
    this.touch();
    this.emit('game:started', {});
    this.emit('melody:phase', { phase: 'intro', duration: 5 });
    if (this.mode === 'chart') {
      this.host(`В эфире ${HOST_NAME}! Сегодня — НАСТОЯЩИЕ треки: угадал с 3 секунд — 30 очков, с 7 — 20, с 15 — 10. Настраиваю волну…`);
      this.beginChartResolution();
    } else {
      this.host(`Здорово, меломаны! Я ${HOST_NAME} — сегодня играю мелодии по нотам. Угадал с 4 нот — 30 очков, с 8 — 20, со всей мелодии — 10. Поехали!`);
    }
    this.registerTimeout(() => this.startRound(), 5000);
    return this;
  }

  /** Фоновый резолв превью iTunes для чарт-режима (недоступные треки выпадают). */
  beginChartResolution() {
    const picks = shuffle(CHART_TRACKS).slice(0, this.maxRounds + 8);
    Promise.allSettled(picks.map(async (t) => {
      const p = await this._resolvePreview(t);
      return p ? { ...t, ...p, category: 'Чарт' } : null;
    })).then((results) => {
      this.chartPool = results
        .filter((r) => r.status === 'fulfilled' && r.value)
        .map((r) => r.value);
    }).catch(() => { this.chartPool = []; });
  }

  startRound() {
    if (this.phase === 'gameOver') return;
    if (this.round >= this.maxRounds) return this.endGame();

    if (this.mode === 'chart') {
      if (this.chartPool === null) {
        // превью ещё резолвятся — ждём, но не бесконечно
        this._chartRetries += 1;
        if (this._chartRetries <= 8) {
          if (this._chartRetries === 2) this.host('Ловлю сигнал со спутника… секунду!');
          this.registerTimeout(() => this.startRound(), 1500);
          return;
        }
        this.chartPool = [];
      }
      if (this.chartPool.length === 0) {
        // интернет/стор недоступен — честно падаем в ноты
        this.mode = 'notes';
        this.host('Антенна барахлит — эфир с реальными треками недоступен. Переключаюсь на верный синтезатор!');
      }
    }

    this.round += 1;
    this.attempt = 0;
    this._roundWinner = null;
    if (this.mode === 'chart') {
      if (this.poolIdx >= this.chartPool.length) { this.chartPool = shuffle(this.chartPool); this.poolIdx = 0; }
      this.current = this.chartPool[this.poolIdx++];
    } else {
      if (this.poolIdx >= this.pool.length) { this.pool = shuffle(this._notesBank); this.poolIdx = 0; }
      this.current = this.pool[this.poolIdx++];
    }
    this.host(this.round === 1
      ? 'Раунд первый. Внимание на колонки!'
      : `Раунд ${this.round} из ${this.maxRounds}. Слушаем!`);
    this.nextAttempt();
  }

  nextAttempt() {
    if (this.phase === 'gameOver' || !this.current) return;
    this.attempt += 1;
    this._hintUsedThisAttempt = false;
    if (this.attempt > 3) return this.reveal(null);
    this.phase = 'guessing';
    this.touch();

    const isChart = this.mode === 'chart';
    const n = isChart ? 0 : ATTEMPT_NOTES[this.attempt - 1];
    const notes = isChart ? null : (n === Infinity ? this.current.notes : this.current.notes.slice(0, n));
    const secs = isChart ? CHART_SECONDS[this.attempt - 1] : 0;
    const lines = isChart
      ? [
        `Категория — «Чарт». ${secs} секунды трека! Кто узнает — ${ATTEMPT_POINTS[0]} очков!`,
        `Тишина в студии? Даю ${secs} секунд. На кону ${ATTEMPT_POINTS[1]}.`,
        `Последний шанс: ${secs} секунд! Всего ${ATTEMPT_POINTS[2]}, но лучше, чем ноль!`,
      ]
      : [
        `Категория — «${this.current.category}». Первые ${notes.length} ноты. Кто самый быстрый — ${ATTEMPT_POINTS[0]} очков!`,
        `Никто? Держите ещё — уже ${notes.length} нот. Цена вопроса ${ATTEMPT_POINTS[1]}.`,
        `Ладно, вся мелодия целиком! За ${ATTEMPT_POINTS[2]} очков — ну же!`,
      ];
    this.host(lines[this.attempt - 1]);
    if (this.hintsEnabled && this.attempt >= 2) {
      const hint = isChart
        ? (this.attempt === 2
          ? `Исполнитель начинается на «${(this.current.artist || '?')[0].toUpperCase()}»`
          : `Это же ${this.current.artist}! Осталось вспомнить трек.`)
        : this.current.hints[this.attempt - 2];
      if (hint) this.registerTimeout(() => {
        if (this.phase === 'guessing') this.host(`Подсказка: ${hint}`);
      }, 1500);
    }

    this.emit('melody:snippet', {
      round: this.round, maxRounds: this.maxRounds,
      attempt: this.attempt, points: ATTEMPT_POINTS[this.attempt - 1],
      notes, bpm: this.current.bpm,
      previewUrl: isChart ? this.current.previewUrl : null,
      playSeconds: isChart ? secs : null,
      category: this.current.category,
      duration: this.attemptTime,
    });
    this.emit('melody:phase', { phase: 'guessing', duration: this.attemptTime, round: this.round, attempt: this.attempt });
    this._attemptTimer = this.registerTimeout(() => this.nextAttempt(), this.attemptTime * 1000);
  }

  submitGuess(playerId, text) {
    if (this.phase !== 'guessing' || !this.current) return { ok: false, error: 'Сейчас не приём ответов — дождитесь нот!' };
    const player = this.getPlayer(playerId);
    if (!player) return { ok: false, error: 'Вы не в этой игре' };
    const guess = String(text ?? '').trim().slice(0, 100);
    if (guess.length < 2) return { ok: false, error: 'Слишком коротко' };

    const now = Date.now();
    const last = this._cooldown.get(playerId) || 0;
    if (now - last < 1200) return { ok: false, error: 'Секунду, перевожу дух… и снова можно отвечать!' };
    this._cooldown.set(playerId, now);

    if (matchesGuess(guess, this.current)) {
      const points = ATTEMPT_POINTS[this.attempt - 1];
      player.score += points;
      this._roundWinner = { id: playerId, name: player.name, points };
      this.clearManagedTimeout(this._attemptTimer);
      this.touch();
      this.emit('melody:guessed', { playerId, playerName: player.name, points, attempt: this.attempt });
      const how = this.mode === 'chart'
        ? `с ${CHART_SECONDS[this.attempt - 1]} секунд`
        : (this.attempt === 3 ? 'с полной мелодии' : `с ${ATTEMPT_NOTES[this.attempt - 1]} нот`);
      const what = this.mode === 'chart' ? `${this.current.artist} — «${this.current.title}»` : `«${this.current.title}»`;
      this.host(`${player.name} угадывает ${how} — плюс ${points}! Это ${what}.`);
      this.reveal(this._roundWinner);
      return { ok: true, correct: true };
    }

    this.emit('melody:guess-wrong', { playerId, playerName: player.name, guess });
    return { ok: true, correct: false };
  }

  /** Ручная подсказка (кнопка «Подсказка у DJ») — раз на попытку. */
  emitHint() {
    if (!this.hintsEnabled || this.phase !== 'guessing' || !this.current) return;
    if (this._hintUsedThisAttempt) return;
    this._hintUsedThisAttempt = true;
    const hint = this.current.hints[Math.min(this.attempt - 1, this.current.hints.length - 1)];
    if (hint) this.host(`Так уж и быть, подсказка: ${hint}`);
  }

  reveal(winner) {
    if (this.phase === 'gameOver') return;
    this.phase = 'reveal';
    this.touch();
    const isChart = this.mode === 'chart';
    if (!winner) {
      const what = isChart ? `${this.current.artist} — «${this.current.title}»` : `«${this.current.title}»`;
      this.host(`Никто не угадал! Это ${isChart ? 'был' : 'была'} ${what}. Слушаем и едем дальше.`);
    }
    this.emit('melody:reveal', {
      round: this.round,
      title: this.current.title,
      artist: isChart ? this.current.artist : null,
      artwork: isChart ? this.current.artwork : null,
      previewUrl: isChart ? this.current.previewUrl : null,
      playSeconds: isChart ? 20 : null,
      notes: isChart ? null : this.current.notes,
      bpm: this.current.bpm,
      winner,
      scoreboard: this.scoreboard(),
    });
    this.emit('melody:phase', { phase: 'reveal', duration: 7, round: this.round });
    this.registerTimeout(() => this.startRound(), 7000);
  }

  scoreboard() {
    return [...this.players].sort((a, b) => b.score - a.score).map((p) => ({ id: p.id, name: p.name, score: p.score }));
  }

  endGame() {
    this.phase = 'gameOver';
    this.touch();
    const board = this.scoreboard();
    const top = board[0];
    this.host(top && top.score > 0
      ? `Финал! Лучшее ухо вечера — ${top.name} с ${top.score} очками. До встречи в эфире!`
      : 'Финал! Сегодня без чемпионов — тренируйте слух и возвращайтесь!');
    this.emit('game:ended', { winner: top || null, scoreboard: board });
  }

  handleAction(playerId, action = {}) {
    switch (action.type) {
      case 'guess': case 'answer': case 'melody-guess':
        return this.submitGuess(playerId, action.text ?? action.guess ?? action.value);
      case 'melody-hint': case 'hint':
        return this.emitHint();
      default: return { ok: false };
    }
  }

  getState() {
    const n = this.attempt > 0 ? ATTEMPT_NOTES[this.attempt - 1] : 0;
    return {
      phase: this.phase,
      round: this.round,
      maxRounds: this.maxRounds,
      attempt: this.attempt,
      points: this.attempt > 0 ? ATTEMPT_POINTS[Math.min(this.attempt, 3) - 1] : 0,
      hintsEnabled: this.hintsEnabled,
      mode: this.mode,
      // текущий сниппет для реконнекта (ответ НЕ включаем до reveal)
      snippet: this.phase === 'guessing' && this.current
        ? (this.mode === 'chart'
          ? { previewUrl: this.current.previewUrl, playSeconds: CHART_SECONDS[Math.min(this.attempt, 3) - 1], category: 'Чарт' }
          : { notes: n === Infinity ? this.current.notes : this.current.notes.slice(0, n), bpm: this.current.bpm, category: this.current.category })
        : null,
      scoreboard: this.scoreboard(),
      version: this.stateVersion,
    };
  }

  getPlayerState() { return this.getState(); }
}
